import { spawnSync } from 'node:child_process';

const PROG = 'argparse_runner.mjs';
const RUNNER = '/tmp/argparse_runner.mjs';

const usage = `usage: ${PROG} [-h] --payload PAYLOAD\n`;
const help =
  usage +
  '\n' +
  'options:\n' +
  '  -h, --help         show this help message and exit\n' +
  '  --payload PAYLOAD\n';

function run(args) {
  const r = spawnSync('node', [RUNNER, ...args], { encoding: 'utf8' });
  return { stdout: r.stdout, stderr: r.stderr, code: r.status };
}

const okOut = (payload) => JSON.stringify({ payload }) + '\n';
const err = (msg) => usage + `${PROG}: error: ${msg}\n`;

const cases = [
  // (1) help anywhere -> stdout, exit 0
  { args: ['-h'], stdout: help, stderr: '', code: 0 },
  { args: ['--help'], stdout: help, stderr: '', code: 0 },
  { args: ['--he'], stdout: help, stderr: '', code: 0 },
  { args: ['--h'], stdout: help, stderr: '', code: 0 },
  { args: ['--payload', 'x', '-h'], stdout: help, stderr: '', code: 0 },
  { args: ['--unknown', '-h'], stdout: help, stderr: '', code: 0 },

  // (2) missing --payload -> stderr, exit 2
  { args: [], stdout: '', stderr: err('the following arguments are required: --payload'), code: 2 },
  { args: ['--unknown', 'x'], stdout: '', stderr: err('the following arguments are required: --payload'), code: 2 },

  // (3) --payload with no value / option-like next token
  { args: ['--payload'], stdout: '', stderr: err('argument --payload: expected one argument'), code: 2 },
  { args: ['--payload', '--unknown'], stdout: '', stderr: err('argument --payload: expected one argument'), code: 2 },
  { args: ['--payload', '-h'], stdout: '', stderr: err('argument --payload: expected one argument'), code: 2 },
  { args: ['--payload', '--'], stdout: '', stderr: err('argument --payload: expected one argument'), code: 2 },

  // (4) unrecognized arguments (required present)
  { args: ['--payload', 'ok', '--unknown', 'x'], stdout: '', stderr: err('unrecognized arguments: --unknown x'), code: 2 },
  { args: ['--payload', 'ok', 'stray'], stdout: '', stderr: err('unrecognized arguments: stray'), code: 2 },
  { args: ['--payload', 'ok', '--unknown'], stdout: '', stderr: err('unrecognized arguments: --unknown'), code: 2 },
  { args: ['--payload', 'ok', '-z'], stdout: '', stderr: err('unrecognized arguments: -z'), code: 2 },

  // (5) = form, abbreviations, -- separator
  { args: ['--payload=test_data_4'], stdout: okOut('test_data_4'), stderr: '', code: 0 },
  { args: ['--payload', 'test_data_4'], stdout: okOut('test_data_4'), stderr: '', code: 0 },
  { args: ['--pay', 'v'], stdout: okOut('v'), stderr: '', code: 0 },
  { args: ['--p', 'v'], stdout: okOut('v'), stderr: '', code: 0 },
  { args: ['--pay=v'], stdout: okOut('v'), stderr: '', code: 0 },
  { args: ['--p=v'], stdout: okOut('v'), stderr: '', code: 0 },
  { args: ['--payload='], stdout: okOut(''), stderr: '', code: 0 },
  { args: ['--', '--payload', 'x'], stdout: '', stderr: err('the following arguments are required: --payload'), code: 2 },
  { args: ['--payload', 'a', '--', 'b'], stdout: '', stderr: err('unrecognized arguments: b'), code: 2 },
  { args: ['--payload', 'a', '--', '-h'], stdout: '', stderr: err('unrecognized arguments: -h'), code: 2 },

  // value edge cases
  { args: ['--payload', '-5'], stdout: okOut('-5'), stderr: '', code: 0 },
  { args: ['--payload', '-3.14'], stdout: okOut('-3.14'), stderr: '', code: 0 },
  { args: ['--payload', '-'], stdout: okOut('-'), stderr: '', code: 0 },
  { args: ['--payload', ''], stdout: okOut(''), stderr: '', code: 0 },
  { args: ['--payload', 'a b'], stdout: okOut('a b'), stderr: '', code: 0 },

  // (6) repeated --payload -> last wins
  { args: ['--payload', 'a', '--payload', 'b'], stdout: okOut('b'), stderr: '', code: 0 },
  { args: ['--payload=a', '--payload=b'], stdout: okOut('b'), stderr: '', code: 0 },
];

let failures = 0;
for (const c of cases) {
  const got = run(c.args);
  const problems = [];
  if (got.stdout !== c.stdout) problems.push(`stdout ${JSON.stringify(got.stdout)} != ${JSON.stringify(c.stdout)}`);
  if (got.stderr !== c.stderr) problems.push(`stderr ${JSON.stringify(got.stderr)} != ${JSON.stringify(c.stderr)}`);
  if (got.code !== c.code) problems.push(`code ${got.code} != ${c.code}`);
  if (problems.length) {
    failures++;
    console.log(`FAIL ${JSON.stringify(c.args)}: ${problems.join('; ')}`);
  } else {
    console.log(`PASS ${JSON.stringify(c.args)}`);
  }
}
console.log(failures === 0 ? `ALL ${cases.length} CASES PASSED` : `${failures} FAILURES`);
process.exit(failures === 0 ? 0 : 1);
